 useEffect(()=>{if(!session||!supabaseReady||!chatId||String(chatId).startsWith('local-'))return;let active=true;
  const refresh=async()=>{
   const {data,error}=await supabase.from('messages').select('id,sender_id,content,file_url,message_type,created_at').eq('conversation_id',chatId).order('created_at',{ascending:false}).limit(200);
   if(error||!data||!active)return;
   setChatHistoryHasMore(v=>({...v,[chatId]:data.length>=200}));
   const rows=[...data].reverse();
   const senderIds=[...new Set(rows.map(m=>m.sender_id).filter(Boolean))];
   const {data:senderProfiles}=senderIds.length?await supabase.from('profiles').select('id,username,display_name,avatar_url').in('id',senderIds):{data:[]};
   const senderMap=new Map((senderProfiles||[]).map(p=>[p.id,p]));
   const messages=await Promise.all(rows.map(async m=>{let fileUrl=m.file_url||'';if(fileUrl&&!fileUrl.startsWith('http')){const {data:signed}=await supabase.storage.from('chat-files').createSignedUrl(fileUrl,3600);fileUrl=signed?.signedUrl||''}const sender=senderMap.get(m.sender_id)||{};return {id:m.id,sender_id:m.sender_id,sender_username:sender.username||sender.display_name||'',sender_avatar:sender.avatar_url||'',created_at:m.created_at,from:m.sender_id===session.user.id?'me':'them',text:m.content||'',file_url:fileUrl,message_type:m.message_type||'text',time:new Date(m.created_at).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}}));
   if(!active)return;
   const ids=rows.map(m=>m.id);
   const unread=rows.filter(m=>m.sender_id!==session.user.id).map(m=>({message_id:m.id,user_id:session.user.id}));
   if(unread.length)await supabase.from('message_reads').upsert(unread,{onConflict:'message_id,user_id',ignoreDuplicates:true});
   const [reactionResult,pinResult,readResult]=await Promise.all([
    ids.length?supabase.from('message_reactions').select('message_id,user_id,emoji').in('message_id',ids):Promise.resolve({data:[],error:null}),
    supabase.from('conversation_pins').select('message_id').eq('conversation_id',chatId),
    ids.length?supabase.from('message_reads').select('message_id,user_id').in('message_id',ids):Promise.resolve({data:[],error:null})
   ]);
   if(!active)return;
   if(!reactionResult.error){setLocalMessageReactions(v=>{const next={...v};ids.forEach(id=>delete next[id]);(reactionResult.data||[]).forEach(r=>{next[r.message_id]={...(next[r.message_id]||{}),[r.user_id]:r.emoji}});return next})}
   if(!pinResult.error)setPinnedMessageIds(v=>({...v,[chatId]:(pinResult.data||[]).map(p=>p.message_id)}));
   if(!readResult.error){const sentIds=new Set(rows.filter(m=>m.sender_id===session.user.id).map(m=>m.id));setReadMessageIds((readResult.data||[]).filter(r=>r.user_id!==session.user.id&&sentIds.has(r.message_id)).map(r=>r.message_id))}
   const last=messages[messages.length-1];setConversations(v=>v.map(x=>x.id===chatId?{...x,messages,last:last?.text||x.last,time:last?.time||x.time}:x));
  };
  refresh();const channel=supabase.channel('vyro-chat-'+chatId).on('postgres_changes',{event:'*',schema:'public',table:'messages',filter:'conversation_id=eq.'+chatId},()=>refresh()).on('postgres_changes',{event:'*',schema:'public',table:'message_reactions'},()=>refresh()).on('postgres_changes',{event:'*',schema:'public',table:'conversation_pins',filter:'conversation_id=eq.'+chatId},()=>refresh()).subscribe();const timer=window.setInterval(refresh,60000);return()=>{active=false;window.clearInterval(timer);supabase.removeChannel(channel)}},[session,chatId]);
 useEffect(()=>{if(session){setProfileAvatar(session.user?.user_metadata?.avatar_url||'');setProfileAvatarHistory([...new Set([...(Array.isArray(session.user?.user_metadata?.avatar_history)?session.user.user_metadata.avatar_history:[]),session.user?.user_metadata?.avatar_url].filter(Boolean))].slice(-2));setProfileBanner(session.user?.user_metadata?.banner_url||'');setProfileBio(session.user?.user_metadata?.bio||'به دنیای وایرو خوش اومدی ✨')}},[session]);
