 async function sendChatAttachment(file,messageType='file'){
  if(!file||!chatId)return;
  if(!session||!supabaseReady||String(chatId).startsWith('local-')){setNotice('برای ارسال فایل، ابتدا وارد حساب آنلاین شو و گفت‌وگوی آنلاین باز کن.');return}
  setBusy(true);
  try{
   const safeName=(file.name||('vyro-'+Date.now())).replace(/[^a-zA-Z0-9._-]/g,'_');
   const path=`${session.user.id}/${chatId}/${Date.now()}-${safeName}`;
   const {error:uploadError}=await supabase.storage.from('chat-files').upload(path,file,{upsert:false,contentType:file.type||undefined});
   if(uploadError)throw uploadError;
   const {data:signed,error:signedError}=await supabase.storage.from('chat-files').createSignedUrl(path,3600);
   if(signedError)throw signedError;
   const ok=await insertChatMessage({content:file.name||messageType,fileUrl:path,displayUrl:signed.signedUrl,messageType,displayText:file.name||messageType});
   if(!ok)setNotice('فایل بارگذاری شد اما پیام ثبت نشد. دوباره تلاش کن.');
  }catch(err){setNotice('ارسال فایل انجام نشد: '+(err.message||'دسترسی مخزن را بررسی کن.'));setBusy(false)}
 }
