 async function toggleRecording(kind){
  if(recordingKind===kind){try{chatRecorderRef.current?.stop()}catch{}return}
  if(recordingKind){try{chatRecorderRef.current?.stop()}catch{}}
  if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){setNotice('ضبط صدا/ویدیو در این مرورگر پشتیبانی نمی‌شود.');return}
  try{
   const stream=await navigator.mediaDevices.getUserMedia(kind==='video_note'?{audio:true,video:{facingMode:'user'}}:{audio:true});
   chatStreamRef.current=stream;
   const recorder=new MediaRecorder(stream);chatRecorderRef.current=recorder;const chunks=[];
   recorder.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};
   recorder.onerror=()=>{stream.getTracks().forEach(t=>t.stop());setRecordingKind(null);setNotice('ضبط انجام نشد. مجوز میکروفون/دوربین را بررسی کن.')};
   recorder.onstop=async()=>{
    stream.getTracks().forEach(t=>t.stop());chatStreamRef.current=null;chatRecorderRef.current=null;setRecordingKind(null);
    if(!chunks.length)return;
    const mime=chunks[0].type|| (kind==='video_note'?'video/webm':'audio/webm');
    const ext=mime.includes('mp4')?'mp4':mime.includes('ogg')?'ogg':'webm';
    const file=new File([new Blob(chunks,{type:mime})],`vyro-${kind}-${Date.now()}.${ext}`,{type:mime});
    await sendChatAttachment(file,kind);
   };
   recorder.start();setRecordingKind(kind);setNotice(kind==='video_note'?'ضبط ویدیویی شروع شد؛ برای پایان دوباره روی دکمه بزن.':'ضبط ویس شروع شد؛ برای پایان دوباره روی دکمه بزن.');
  }catch(err){setNotice('اجازهٔ میکروفون/دوربین داده نشد: '+(err.message||'تنظیمات مرورگر را بررسی کن.'));setRecordingKind(null)}
 }
